 public HandoffRecord recordHandoff(String w0,String from0,String to0,String sd0,String cp,List<String> effects,List<String>signals,List<String>blockers,Instant at){final String w=req(w0),from=req(from0),to=req(to0),sd=req(sd0);Objects.requireNonNull(at);final var rs=Objects.requireNonNull(r.current(w));if(!rs.stateDigest().equals(sd))throw new StaleStateException("state");if(!a.mayRecord(from,w,rs.recoveryEpoch(),at))throw new UnauthorizedActorException("record");final var e=copy(effects);final var s=copy(signals);final var b=copy(blockers);final String dg=handoffDigest(w,rs.recoveryEpoch(),from,to,sd,cp,e,s,b),id="handoff-"+dg.substring(0,24);final var n=new HandoffRecord(id,w,rs.recoveryEpoch(),from,to,sd,cp,e,s,b,at,dg,HandoffRecord.AdoptionState.PENDING,null,null,1);return tx(x->{var old=x.byId.get(id);if(old!=null){if(!old.handoffDigest().equals(dg))throw new SemanticConflictException("intent");return new Dec<>(old,null);}var cur=x.current.get(w);if(cur!=null&&cur.recoveryEpoch()>rs.recoveryEpoch())throw new StaleStateException("newer");return new Dec<>(n,frame(n));});}
 public HandoffRecord adoptHandoff(String id0,String actor0,long epoch,Instant at){final String id=req(id0),actor=req(actor0);Objects.requireNonNull(at);return tx(x->{var h=x.byId.get(id);if(h==null)throw new UnknownHandoffException("unknown");var rs=Objects.requireNonNull(r.current(h.workUnitId()));if(epoch!=rs.recoveryEpoch()||h.recoveryEpoch()!=rs.recoveryEpoch()||!h.stateDigest().equals(rs.stateDigest())){var z=rep(h,HandoffRecord.AdoptionState.STALE,null,null);return new Dec<>(z,frame(z));}if(h.adoptionState()==HandoffRecord.AdoptionState.ADOPTED){if(actor.equals(h.adoptedByActorRef()))return new Dec<>(h,null);throw new SemanticConflictException("already adopted");}if(!a.mayAdopt(actor,h.workUnitId(),h.recoveryEpoch(),h.toRoleOrActorRef(),at)){var z=rep(h,HandoffRecord.AdoptionState.BLOCKED,null,null);return new Dec<>(z,frame(z));}var z=rep(h,HandoffRecord.AdoptionState.ADOPTED,actor,at);return new Dec<>(z,frame(z));});}
 public HandoffState getHandoffState(String w0){String w=req(w0);var h=snap().current.get(w);if(h==null)return new HandoffState(null,List.of(),HandoffRecord.AdoptionState.BLOCKED,HandoffState.Freshness.UNAVAILABLE);var rs=r.current(w);var fr=rs==null?HandoffState.Freshness.UNKNOWN:(rs.recoveryEpoch()==h.recoveryEpoch()&&rs.stateDigest().equals(h.stateDigest())?HandoffState.Freshness.CURRENT:HandoffState.Freshness.STALE);var o=new ArrayList<String>();o.addAll(h.unresolvedEffectRefs());o.addAll(h.pendingSignalRefs());o.addAll(h.blockerRefs());return new HandoffState(h,o,h.adoptionState(),fr);}
 private static HandoffRecord rep(HandoffRecord h,HandoffRecord.AdoptionState st,String actor,Instant at){return new HandoffRecord(h.handoffId(),h.workUnitId(),h.recoveryEpoch(),h.fromActorRef(),h.toRoleOrActorRef(),h.stateDigest(),h.checkpointRef(),h.unresolvedEffectRefs(),h.pendingSignalRefs(),h.blockerRefs(),h.createdAt(),h.handoffDigest(),st,actor,at,h.version()+1);}
 private Snap snap(){return lock((c,s)->s);}private <T>T tx(Tx<T> q){return lock((c,s)->{var d=q.go(s);if(d.line!=null)append(c,d.line);return d.v;});}private <T>T lock(Locked<T> q){try(FileChannel c=FileChannel.open(f,StandardOpenOption.READ,StandardOpenOption.WRITE);FileLock l=c.lock()){return q.go(c,replay(c));}catch(IOException e){throw new IllegalStateException(e);}}
 private Snap replay(FileChannel c)throws IOException{Map<String,HandoffRecord> ids=new HashMap<>(),cur=new HashMap<>();long z=c.size();if(z>Integer.MAX_VALUE)throw new IntegrityException("large");ByteBuffer bb=ByteBuffer.allocate((int)z);c.position(0);while(bb.hasRemaining()&&c.read(bb)>=0){}bb.flip();for(String line:StandardCharsets.UTF_8.decode(bb).toString().split("\\R",-1)){if(line.isBlank())continue;int p=line.lastIndexOf('\t');if(p<1)throw new IntegrityException("truncated");String body=line.substring(0,p);if(!sha(body).equals(line.substring(p+1)))throw new IntegrityException("checksum");String[]v=body.split("\\|",-1);if(v.length!=17)throw new IntegrityException("width");var h=decode(v);ids.put(h.handoffId(),h);var q=cur.get(h.workUnitId());if(q==null||h.recoveryEpoch()>q.recoveryEpoch()||(h.recoveryEpoch()==q.recoveryEpoch()&&h.version()>=q.version()))cur.put(h.workUnitId(),h);}return new Snap(Map.copyOf(ids),Map.copyOf(cur));}
