 private static HandoffRecord decode(String[]v){return new HandoffRecord(dec(v[1]),dec(v[2]),Long.parseLong(v[3]),dec(v[4]),dec(v[5]),dec(v[6]),decN(v[7]),split(dec(v[8])),split(dec(v[9])),split(dec(v[10])),Instant.parse(v[11]),dec(v[12]),HandoffRecord.AdoptionState.valueOf(v[13]),decN(v[14]),v[15].isEmpty()?null:Instant.parse(v[15]),Long.parseLong(v[16]));}
 public static String handoffDigest(String w,long ep,String from,String to,String sd,String cp,List<String>e,List<String>s,List<String>b){return sha(String.join("|",req(w),""+ep,req(from),req(to),req(sd),cp==null?"":cp.trim(),String.join(",",copy(e)),String.join(",",copy(s)),String.join(",",copy(b))));}private static String sha(String s){try{byte[]x=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte q:x)b.append(String.format("%02x",q));return b.toString();}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static List<String> split(String s){return s.isEmpty()?List.of():List.of(s.split("\\u001f",-1));}private static List<String> copy(List<String>x){return List.copyOf(x==null?List.of():x);}private static String req(String x){if(x==null||x.trim().isEmpty())throw new IllegalArgumentException("required");return x.trim();}private static String enc(String s){return E.encodeToString(s.getBytes(StandardCharsets.UTF_8));}private static String dec(String s){return new String(D.decode(s),StandardCharsets.UTF_8);}private static String encN(String s){return s==null?"":enc(s);}private static String decN(String s){return s.isEmpty()?null:dec(s);}
 public record RecoverySnapshot(long recoveryEpoch,String stateDigest,String currentFenceRef){public RecoverySnapshot{if(recoveryEpoch<1)throw new IllegalArgumentException("epoch");stateDigest=req(stateDigest);currentFenceRef=req(currentFenceRef);}}@FunctionalInterface public interface RecoveryAuthority{RecoverySnapshot current(String workUnitId);}public interface ActorAuthority{boolean mayRecord(String actorRef,String workUnitId,long recoveryEpoch,Instant at);boolean mayAdopt(String actorRef,String workUnitId,long recoveryEpoch,String requestedRoleOrActor,Instant at);}private record Snap(Map<String,HandoffRecord>byId,Map<String,HandoffRecord>current){}private record Dec<T>(T v,String line){}private interface Tx<T>{Dec<T>go(Snap s);}private interface Locked<T>{T go(FileChannel c,Snap s)throws IOException;}public static final class IntegrityException extends RuntimeException{IntegrityException(String m){super(m);}}public static final class StaleStateException extends RuntimeException{StaleStateException(String m){super(m);}}public static final class UnauthorizedActorException extends RuntimeException{UnauthorizedActorException(String m){super(m);}}public static final class UnknownHandoffException extends RuntimeException{UnknownHandoffException(String m){super(m);}}public static final class SemanticConflictException extends RuntimeException{SemanticConflictException(String m){super(m);}}
